The invariant is that size stays between 0 and 17, head points to the next element to pop, and the next insertion slot is (head + size) % 17. A full queue rejects push without changing state; an empty queue returns no value on pop. This is a single-threaded integer FIFO.

```cpp
#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
#include <stdexcept>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (size_ == capacity) return false;
        data_[(head_ + size_) % capacity] = value;
        ++size_;
        return true;
    }

    std::optional<int> pop() {
        if (size_ == 0) return std::nullopt;
        int value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

void check(bool condition) {
    if (!condition) throw std::runtime_error("Test failed");
}

int main() {
    BoundedFIFO queue;
    check(!queue.pop().has_value());

    // Fill and reject overflow without changing the contents.
    for (int i = 0; i < 17; ++i) check(queue.push(i));
    check(queue.size() == 17);
    check(!queue.push(999));
    check(queue.size() == 17);

    // Drain in FIFO order and reject an empty pop.
    for (int i = 0; i < 17; ++i) {
        check(queue.pop() == std::optional<int>{i});
    }
    check(queue.size() == 0);
    check(!queue.pop().has_value());

    // Wrap insertion around while retaining seven older elements.
    for (int i = 0; i < 17; ++i) check(queue.push(i));
    for (int i = 0; i < 10; ++i) {
        check(queue.pop() == std::optional<int>{i});
    }
    for (int i = 17; i < 27; ++i) check(queue.push(i));
    check(queue.size() == 17);
    check(!queue.push(999));
    for (int i = 10; i < 27; ++i) {
        check(queue.pop() == std::optional<int>{i});
    }
    check(queue.size() == 0);
    check(!queue.pop().has_value());
    std::cout << "All tests passed\n";
}
```

Save as `fifo.cpp`, compile with `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo`, then run `./fifo` (or `fifo.exe` on Windows).
